import React, { useState, useRef, useEffect } from 'react';
import { Pose } from '@mediapipe/pose';
import { Upload, Sparkles, Loader2, CheckCircle } from 'lucide-react';
import './styles/VirtualTryOn.css';

const VirtualTryOn = () => {
  const [userImg, setUserImg] = useState(null); // From Profile
  const [garmentImg, setGarmentImg] = useState(null); // User Upload
  const [resultImg, setResultImg] = useState(null);
  const [isProcessing, setIsProcessing] = useState(false);
  
  const canvasRef = useRef(null);
  const poseRef = useRef(null);

  useEffect(() => {
    // 1. Fetch User Profile Photo
    const fetchUserPhoto = async () => {
      const token = localStorage.getItem('token');
      const res = await fetch('http://localhost:5000/api/profile', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      setUserImg(data.fullBodyImage);
    };

    // 2. Init MediaPipe
    poseRef.current = new Pose({
      locateFile: (file) => `https://cdn.jsdelivr.net/npm/@mediapipe/pose/${file}`,
    });
    poseRef.current.setOptions({ modelComplexity: 1, smoothLandmarks: true });
    
    fetchUserPhoto();
  }, []);

  const handleGarmentUpload = (e) => {
    const file = e.target.files[0];
    const reader = new FileReader();
    reader.onloadend = () => setGarmentImg(reader.result);
    if (file) reader.readAsDataURL(file);
  };

  const generateTryOn = async () => {
    setIsProcessing(true);
    
    // Run Pose Detection to get coordinates for masking
    const imgElement = new Image();
    imgElement.src = userImg;
    imgElement.crossOrigin = "anonymous";
    
    imgElement.onload = async () => {
      const results = await poseRef.current.send({ image: imgElement });
      
      // Send Base Image, Garment Image, and Pose Landmarks to Backend
      try {
        const response = await fetch('http://localhost:5000/api/ai/tryon', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            baseImage: userImg,
            garmentImage: garmentImg,
            landmarks: results.poseLandmarks // Used by backend for inpainting mask
          })
        });

        const data = await response.json();
        setResultImg(data.outputUrl);
      } catch (err) {
        console.error("AI Generation Error:", err);
      } finally {
        setIsProcessing(false);
      }
    };
  };

  return (
    <div className="vto-layout">
      {/* LEFT: INPUTS */}
      <div className="vto-panel">
        <h3>1. Your Base Model</h3>
        <div className="vto-preview-box">
          <img src={userImg} alt="User" />
        </div>

        <h3>2. Upload New Garment</h3>
        <div className="upload-zone" onClick={() => document.getElementById('garmentInput').click()}>
          {garmentImg ? <img src={garmentImg} alt="Garment" /> : <Upload size={40} />}
          <input type="file" id="garmentInput" hidden onChange={handleGarmentUpload} />
        </div>

        <button 
          className="generate-btn" 
          disabled={!garmentImg || isProcessing} 
          onClick={generateTryOn}
        >
          {isProcessing ? <Loader2 className="spinner" /> : <Sparkles />} Generate AI Look
        </button>
      </div>

      {/* RIGHT: OUTPUT */}
      <div className="vto-panel output-panel">
        <h3>AI Result</h3>
        <div className="vto-preview-box result-box">
          {isProcessing && <div className="scanning-bar" />}
          {resultImg ? <img src={resultImg} alt="Result" /> : <p>Waiting for generation...</p>}
        </div>
      </div>
    </div>
  );
};

export default VirtualTryOn;
